sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        g_form.hideFieldMsg('intake_seats', true);
        return;
    }

    var seats = parseInt(newValue, 10);
    g_form.hideFieldMsg('intake_seats', true);

    if (isNaN(seats) || seats <= 0) {
        g_form.showFieldMsg('intake_seats', 'Intake seats must be greater than zero.', 'error');
    }
}
